	protected bool resizeTerminal(int cols, int rows) {
		bool affected;
		lock (@lock) {
			affected = buffer.resize(cols, rows);
			bufPrimary.resize(cols, rows);
			bufAlternate.resize(cols, rows);
		}
		if (affected) {
			Swing.runIfSwingOrRunLater(() => {
				modelChanged();
				panel.placeCursor(true);
			});
		}
		return affected;
	}

